/**
 * Tripwire — the plugin's `runtime/` directory is the capability list and the capability template, nothing else:
 * `capabilities.md`, a closed set of capabilities with the fallbacks and the template a description is written from.
 * The plugin carries no description of any runtime; each machine's own are generated by `setup` and live in the
 * project, in home or in `~/.idea-loop/` (spec dyna-app-layer-cleanup). What went with them, and why:
 *   - the per-runtime assertions (which tool a section names, which commands magi's dispatch uses): those descriptions
 *     are not the plugin's any more, so what they say is no longer something the plugin can pin;
 *   - the description of the removed runtime skill ("description only routes", the detection rule, how to add a
 *     runtime): moved into `dyna runtime --help` (dyna/internal/runtime tests); the fallback and its two exceptions
 *     are still asserted here, on capabilities.md.
 */
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync, readdirSync, mkdtempSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { runDyna } from './dyna-test-bin.mjs';

const pluginRoot = join(dirname(fileURLToPath(import.meta.url)), '..');
const dir = join(pluginRoot, 'runtime');
const read = (name) => readFileSync(join(dir, name), 'utf8');
const capabilitiesMd = read('capabilities.md');

const CAPABILITIES = ['定时任务', '会话内循环', '会话管理', '浏览器', '人的浏览器', '向人提问', '发布审阅页', '推送', '发文件给人', '调用 MCP', '装与设置'];

/** The capability names in the first column of the table under 「能力清单」. */
export function capabilitiesOf(text) {
  const start = text.indexOf('## 能力清单');
  assert.ok(start >= 0, 'no 能力清单 section');
  const rest = text.slice(start + 1);
  const end = rest.search(/\n## /);
  const section = rest.slice(0, end < 0 ? undefined : end);
  return section.split('\n').filter((l) => l.startsWith('|')).slice(2).map((l) => l.split('|')[1].trim());
}

/** The `##` section names of a runtime's data. */
export const sectionsOf = (text) => [...text.matchAll(/^## (.+)$/gm)].map((m) => m[1].trim());

/** What a runtime's data lacks (missing) or adds (extra) compared with the capability list. */
export function diff(capabilities, sections) {
  return {
    missing: capabilities.filter((c) => !sections.includes(c)),
    extra: sections.filter((s) => !capabilities.includes(s)),
  };
}

test('the capability list is the closed set of eleven', () => {
  assert.deepEqual(capabilitiesOf(capabilitiesMd), CAPABILITIES);
});

/** The text of one `##` section of a runtime's data. */
const sectionText = (text, name) => {
  const start = text.indexOf(`\n## ${name}\n`);
  assert.ok(start >= 0, `no ${name} section`);
  const rest = text.slice(start + 1);
  const end = rest.slice(3).search(/\n## /);
  return end < 0 ? rest : rest.slice(0, end + 3);
};

test('人的浏览器: the table row says it carries the human\'s own login, and the fallback is the shared one', () => {
  const row = capabilitiesMd.split('\n').find((l) => l.startsWith('| 人的浏览器 |'));
  assert.ok(row, 'no 人的浏览器 row');
  assert.match(row, /人自己的浏览器/);
  assert.match(row, /登录态/);
  assert.match(row, /退路\s*\|$/);
});

test('capabilities.md states the fallback with its two exceptions and asking in the conversation, and nothing about the removed skill', () => {
  const fallback = capabilitiesMd.slice(capabilitiesMd.indexOf('## 退路'));
  assert.match(fallback, /未做：运行环境/);
  assert.match(fallback, /例外一[\s\S]*issue-dispatch[\s\S]*停下/);
  assert.match(fallback, /例外二[\s\S]*分组/);
  assert.match(fallback, /向人提问[\s\S]*对话里问/);
  for (const gone of ['## 怎么用', '## 检测规则', '## 加一种运行环境', 'runtime-detect.mjs', 'idea-loop:runtime']) assert.ok(!capabilitiesMd.includes(gone), gone);
});

test('the runtime directory holds capabilities.md and nothing else: the plugin carries no description of any runtime', () => {
  assert.deepEqual(readdirSync(dir).sort(), ['capabilities.md']);
});

// spec runtime-ops-in-docs, ticket 02: the template is the one place that says what a description has to answer for each
// capability; `dyna runtime check` reads it, and the two shipped descriptions pass it.
test('the capability template has one ### per capability, in the list\'s order, and every item says what goes in, what comes back and what if not', () => {
  const start = capabilitiesMd.indexOf('\n## 能力模板\n');
  assert.ok(start >= 0, 'no 能力模板 section');
  assert.ok(start > capabilitiesMd.indexOf('\n## 退路\n'), 'the template follows the fallbacks, which stay as they were');
  const section = capabilitiesMd.slice(start + 1);
  const subs = [...section.matchAll(/^### (.+)$/gm)].map((m) => m[1].trim());
  assert.deepEqual(subs, CAPABILITIES);
  const items = section.split('\n').filter((l) => /^- \*\*/.test(l));
  assert.ok(items.length >= CAPABILITIES.length, 'every capability has at least one item');
  for (const line of items) for (const part of ['传入：', '拿回：', '做不到时：']) assert.ok(line.includes(part), `${line} has no ${part}`);
});

test('the example item of the spec is in the template: 会话管理 → 开一个 issue 会话', () => {
  const line = capabilitiesMd.split('\n').find((l) => l.startsWith('- **开一个 issue 会话**'));
  assert.ok(line, 'no 开一个 issue 会话 item');
  for (const word of ['worktree', '标题「<仓库名>#<号> <标题>」', '分组名', 'prompt', '会话 id', '例外一']) assert.ok(line.includes(word), word);
});

/** A description made only of the template's own shape: a marker line and every capability answered 「没有」. */
const bareDescription = (capabilities) => `# sample\n\n标记：没有\n\n${capabilities.map((c) => `## ${c}\n\n没有\n`).join('\n')}`;

test('`dyna runtime check` passes a description that answers every capability in the list, and goes red when one is missing or one is added', () => {
  const home = mkdtempSync(join(tmpdir(), 'runtime-data-doc-'));
  const env = { IDEA_LOOP_PLUGIN_ROOT: pluginRoot, IDEA_LOOP_HOME: home, HOME: home };
  const check = (capabilities, name) => {
    const file = join(home, `${name}.md`);
    writeFileSync(file, bareDescription(capabilities));
    return runDyna(['runtime', 'check', file], { env, cwd: home });
  };
  const ok = check(CAPABILITIES, 'complete');
  assert.equal(ok.status, 0, ok.stdout + ok.stderr);
  const missing = check(CAPABILITIES.slice(1), 'missing');
  assert.notEqual(missing.status, 0);
  assert.match(missing.stdout + missing.stderr, /定时任务/);
  const extra = check([...CAPABILITIES, '新能力'], 'extra');
  assert.notEqual(extra.status, 0);
  assert.match(extra.stdout + extra.stderr, /新能力/);
});

test('the section diff goes red when a capability is missing or one is added', () => {
  const sections = sectionsOf(bareDescription(CAPABILITIES));
  assert.deepEqual(sections, CAPABILITIES);
  assert.deepEqual(diff(CAPABILITIES, sections.slice(1)).missing, ['定时任务']);
  assert.deepEqual(diff(CAPABILITIES, [...sections, '新能力']).extra, ['新能力']);
  const cut = capabilitiesMd.replace(/^\| 推送 \|.*\n/m, '');
  assert.notDeepEqual(capabilitiesOf(cut), CAPABILITIES);
});

test('capabilities.md names no removed skill, script or command', () => {
  for (const gone of ['runtime handoff', 'idea-loop:runtime', 'idea-loop:browser', 'SKILL.md', '.mjs', '${CLAUDE_PLUGIN_ROOT}/scripts']) assert.ok(!capabilitiesMd.includes(gone), gone);
});
